+void CollectedHeap::safepoint_and_oom_during_initialization() {
+  assert(!SafepointSynchronize::is_at_safepoint(), "should not be at a safepoint");
+  VM_OOMDuringInitialization op;
+  VMThread::execute(&op);
+  ShouldNotReachHere();
+}
