+void CollectedHeap::oom_at_safepoint_during_initialization() {
+  assert(SafepointSynchronize::is_at_safepoint(), "should be at a safepoint");
+  vm_exit_during_initialization("java.lang.OutOfMemoryError", "Java heap space");
+}
